Level spec: need rows count based on level; also level uses `state.level`. Let's write:

```
function makeSpec(level, cols) {
  const rows = Math.min(8, 5 + Math.floor((level - 1) / 2));
  const cycle = (level - 1) % 5;
  const cells = [];
  for (let r=0; r<rows; r++) {
    for (let c=0; c<cols; c++) {
      let keep = true;
      let hp = 1;
      if (cycle === 0) {
        keep = !(rows >= 6 && r === 2 && (c === 1 || c === cols-2));
      } else if (cycle === 1) {
        const t = rows === 1 ? 1 : r/(rows-1);
        const half = (cols-1)/2 * (0.32 + 0.68*Math.sqrt(t));
        keep = Math.abs(c-(cols-1)/2) <= half + 0.01;
        if (r>=1 && r<=2 && (c===0 || c===cols-1)) hp=2; // maybe not kept
      } else if (cycle === 2) {
        keep = !((r + c) % 2 === 0 && r > 0 && r < rows-1);
        if (keep && (r + c) % 4 === 1) hp = 2;
      } else if (cycle === 3) {
        const tunnel1 = Math.floor(cols/3), tunnel2 = Math.floor(cols*2/3);
        keep = !((c===tunnel1 || c===tunnel2) && r>0 && r<rows-1);
        if (keep && (r===0 || r===rows-1)) hp=2;
      } else {
        const dr = Math.abs(r-(rows-1)/2)/((rows-1)/2||1);
        const dc = Math.abs(c-(cols-1)/2)/((cols-1)/2||1);
        keep = dr*0.85 + dc <= 1.0;
        if (keep && dr + dc < 0.55) hp = 2;
      }
      if (keep) cells.push({r,c,hp});
    }
  }
  if (cells.length < cols) {
    // safety fill full rows
    cells.length = 0;
    for (let r=0;r<rows;r++) for(let c=0;c<cols;c++) cells.push({r,c,hp:1});
  }
  return {cols, rows, cells, cycle};
}
```
