Brick collide:
```
function brickCollide(b){
 for (const br of state.bricks) {
  if (!br.alive) continue;
  const nx = clamp(b.x, br.x, br.x+br.w), ny=...
  let dx=b.x-nx, dy=b.y-ny;
  let d2=dx*dx+dy*dy;
  if (d2 > b.r*b.r) continue;
  let normalX, normalY, push;
  if (d2 > 1e-6) {
    const d=Math.sqrt(d2);
    normalX=dx/d; normalY=dy/d; push=b.r-d;
  } else {
    // center inside
    const left = b.x - br.x, right = br.x+br.w-b.x, top = b.y-br.y, bot=br.y+br.h-b.y;
    const m=Math.min(left,right,top,bot);
    if(m===left){normalX=-1;normalY=0;push=left+b.r;}
    ...
  }
  // reflect
  const dot = b.vx*normalX + b.vy*normalY;
  if (dot < 0) { b.vx -= 2*dot*normalX; b.vy -= 2*dot*normalY; }
  b.x += normalX*(push+0.2); b.y += normalY*(push+0.2);
  // ensure not stuck inside? 
  hitBrick(br,b);
  return true;
 }
 return false;
}
```
