const Sound = {
  ac:null, master:null, enabled:true,
  ensure() {
    if (!this.enabled) return null;
    if (!this.ac) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      this.ac = new AC();
      this.master = this.ac.createGain();
      this.master.gain.value = 0.22;
      this.master.connect(this.ac.destination);
    }
    if (this.ac.state === 'suspended') this.ac.resume();
    return this.ac;
  },
  setEnabled(on){ this.enabled=on; if (this.master) this.master.gain.value = on?0.22:0; if(on) this.ensure(); },
  note(freq, dur=0.08, type='triangle', vol=0.5, slideTo=null, delay=0){
    if(!this.enabled) return;
    const ac=this.ensure(); if(!ac) return;
    const t0=ac.currentTime + delay;
    const osc=ac.createOscillator(), g=ac.createGain();
    osc.type=type; osc.frequency.setValueAtTime(freq,t0);
    if(slideTo) osc.frequency.exponentialRampToValueAtTime(Math.max(30,slideTo), t0+dur);
    g.gain.setValueAtTime(0.0001,t0);
    g.gain.exponentialRampToValueAtTime(vol,t0+0.008);
    g.gain.exponentialRampToValueAtTime(0.0001,t0+dur);
    osc.connect(g).connect(this.master);
