```js
function makeSpec(level, cols) {
  const cycle=(level-1)%5;
  const rows=Math.min(8, 5+Math.floor((level-1)/2)); // level1 5,3 6,5 7,7 8
  const cells=[];
  const cx=(cols-1)/2;
  for(let r=0;r<rows;r++){
    for(let c=0;c<cols;c++){
      let keep=true;
      if(cycle===1){ // pyramid
        const half = (cols/2)*(0.42+0.58*(r/(rows-1)));
        keep = Math.abs(c-cx) <= half - 0.49; // ensure center
      } else if(cycle===2){ // checker
        keep = (r+c)%2===0 || r===0;
      } else if(cycle===3){ // towers
        const cut = c===Math.floor(cols/3) || c===Math.floor(cols*2/3);
        keep = !(cut && r>0 && r<rows-1) && !(r===rows-2 && c%5===2 && level>2);
      } else if(cycle===4){ // diamond
        const dy=Math.abs(r-(rows-1)/2)/((rows-1)/2||1);
        const dx=Math.abs(c-cx)/(cx||1);
        keep = dx*0.85 + dy*0.75 <= 1.0;
        if(r===Math.floor(rows/2) && c===Math.round(cx)) keep=true;
      }
      if(!keep) continue;
      let hp=1;
      // deterministic armor
      if (level>=2 && ((r*7+c*5+level*3)%13===0) && !(cycle===1 && r===0)) hp=2;
      if (level>=5 && ((r*3+c*11+level*7)%17===0)) hp=3;
      if (cycle===4 && Math.abs(c-cx)<=1 && r>0 && r<rows-2) hp=Math.max(hp,2);
      cells.push({c,r,hp});
    }
  }
  return {cols, rows, cells, cycle};
}
```

