Paddle collision:
```js
function paddleCollision(b){
 const p=S.paddle;
 if (b.vy <= 0) return;
 if (b.y + b.r < p.y) return;
 if (b.y - b.r > p.y + p.h) return;
 if (b.x < p.x-p.w/2 - b.r || b.x > p.x+p.w/2 + b.r) return;
 // must be above top or within thickness
 const overlapTop = b.y + b.r - p.y;
 if (overlapTop < 0) return;
 const hit = clamp((b.x-p.x)/(p.w/2), -1, 1);
 const speed = ballSpeed();
 let angle = hit * 1.12 + clamp(p.vx/1400, -0.16, 0.16);
 angle = clamp(angle, -1.22, 1.22);
 b.vx = Math.sin(angle)*speed;
 b.vy = -Math.cos(angle)*speed;
 b.y = p.y - b.r - 0.5;
 // nudge x out of behind
 if (Math.abs(b.vy) < speed*0.36) { b.vy = -speed*0.36; b.vx = Math.sign(b.vx||1)*Math.sqrt(Math.max(0,speed*speed - b.vy*b.vy)); }
 S.combo=0; updateCombo(); spawn particles; S.paddle.flash=1; Sound.paddle(); S.shake=max(.08);
}
```
Careful: ball could collide with paddle side; we only bounce when above-ish. If ball comes from side, skip is okay; it'll fall. Condition `b.y + b.r` between p.y and p.y+p.h+8. I used >= p.y and <= p.y+p.h. Good.

Also if ball stuck and never launched won't collide.

Brick collision:
```js
function brickCollisions(b){
  for (const br of S.bricks){
    if(!br.alive) continue;
    const nx = clamp(b.x, br.x, br.x+br.w);
    const ny = clamp(b.y, br.y, br.y+br.h);
    let dx=b.x-nx, dy=b.y-ny;
    let d2=dx*dx+dy*dy;
    if (d2 > b.r*b.r) continue;
    // inside?
    let nX,nY,pen;
    if (d2 < 0.0001) {
      const dl=b.x-br.x, dr=br.x+br.w-b.x, dt=b.y-br.y, db=br.y+br.h-b.y;
      const m=Math.min(dl,dr,dt,db);
      if(m===dl){nX=-1;nY=0;pen=dl+b.r}
      ...
    } else {
      const d=Math.sqrt(d2); nX=dx/d; nY=dy/d; pen=b.r-d;
    }
    const dot=b.vx*nX+b.vy*nY;
    if (dot<0){ b.vx -= 2*dot*nX; b.vy -= 2*dot*nY; }
    b.x += nX*(pen+0.2); b.y += nY*(pen+0.2);
    damageBrick(br,b);
    break;
  }
}
```
