Cycle patterns:
```
const cells=[];
for (let r=0;r<rows;r++){
 for (let c=0;c<cols;c++){
   let show=true, hp=1;
   if (cycle===1) { // pyramid
      const half = (cols-1)/2;
      const spread = 0.36 + 0.64 * (r/(rows-1)); // 0..1
      show = Math.abs(c-half) <= half*spread + 0.01;
   } else if (cycle===2) {
      show = !((r+c)%2===0) || r===0 || r===rows-1; // checker with solid top/bottom? maybe
   } else if (cycle===3) {
      const chan = Math.max(1, Math.round(cols*0.18));
      show = !((c===chan || c===cols-1-chan) && r>0 && r<rows-1);
   } else if (cycle===4) {
      const dx = Math.abs(c-(cols-1)/2)/((cols-1)/2 || 1);
      const dy = Math.abs(r-(rows-1)/2)/((rows-1)/2 || 1);
      show = dx*0.9 + dy*1.0 < 1.12;
   }
   if (!show) continue;
   // deterministic armor
   if (level>=2) {
      const n = (r*7 + c*13 + level*5) % 19;
      if (n===0) hp=2;
      if (level>=4 && n===3) hp=3;
      if (level>=8 && n===7) hp=3;
   }
   cells.push({c,r,hp});
 }
}
