const sound = (() => {
  let ac = null, master = null;
  function ensure() {
    if (!state.sound) return null;
    if (!ac) {
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return null;
      ac = new AC();
      master = ac.createGain();
      master.gain.value = 0.16;
      master.connect(ac.destination);
    }
    if (ac.state === 'suspended') ac.resume().catch(()=>{});
    return ac;
  }
  function tone({freq=440, to=null, dur=.08, type='sine', vol=.5, delay=0}) {
    const a = ensure(); if (!a) return;
    const t0 = a.currentTime + delay;
    const osc = a.createOscillator();
    const g = a.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t0);
    if (to != null) osc.frequency.exponentialRampToValueAtTime(Math.max(20,to), t0+dur);
    g.gain.setValueAtTime(0.0001, t0);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0001, vol), t0 + 0.006);
    g.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
    osc.connect(g).connect(master);
    osc.start(t0); osc.stop(t0+dur+0.03);
  }
  const notes = [523.25, 587.33, 659.25, 783.99, 880, 1046.5, 1174.66];
  return {
    unlock(){ ensure(); },
    wall(){ tone({freq:380,to:300,dur:.04,type:'triangle',vol:.25}); },
    paddle(){ tone({freq:220,to:330,dur:.07,type:'square',vol:.28}); },
    brick(combo){ const f = notes[Math.min(notes.length-1, combo % notes.length)]; tone({freq:f,dur:.07,type:'triangle',vol:.4}); tone({freq:f*2,dur:.045,type:'sine',vol:.12}); },
    armor(){ tone({freq:150,to:120,dur:.06,type:'square',vol:.25}); },
    power(){ [0,1,2].forEach((i)=>tone({freq:600+i*200,to:900+i*200,dur:.1,type:'sine',vol:.3,delay:i*.055})); },
    lose(){ tone({freq:250,to:70,dur:.5,type:'sawtooth',vol:.5}); },
    clear(){ [523,659,784,1047].forEach((f,i)=>tone({freq:f,dur:.18,type:'triangle',vol:.35,delay:i*.09})); },
    over(){ [330,262,196].forEach((f,i)=>tone({freq:f,dur:.3,type:'sawtooth',vol:.25,delay:i*.14})); },
    click(){ tone({freq:660,dur:.05,type:'sine',vol:.25}); },
  };
})();
