```
function measure(force=false) {
  const rect = canvas.getBoundingClientRect();
  const W = Math.max(1, Math.round(rect.width));
  const H = Math.max(1, Math.round(rect.height));
  const dpr = Math.min(window.devicePixelRatio || 1, 2);
  const changed = force || W !== world.W || H !== world.H || dpr !== world.dpr;
  if (!changed) return false;
  const oldW=world.W, oldH=world.H;
  world.W=W; world.H=H; world.dpr=dpr;
  canvas.width = Math.round(W*dpr);
  canvas.height = Math.round(H*dpr);
  ctx.setTransform(dpr,0,0,dpr,0,0);
  // metrics
  metrics.padX = clamp(W*0.04, 10, 38);
  metrics.top = clamp(H*0.105, 54, 92);
  metrics.cols = W < 430 ? 7 : W < 700 ? 9 : W < 900 ? 11 : 12;
  metrics.gap = clamp(W*0.0065, 3, 7);
  const field = W - metrics.padX*2;
  metrics.bw = (field - metrics.gap*(metrics.cols-1))/metrics.cols;
  metrics.bh = clamp(H*0.040, 21, 33);
  metrics.rowGap = clamp(metrics.bh*0.22, 4, 8);
  const r = clamp(W*0.0115, 5.5, 8.5);
  world.ballR = r;
  world.speed = clamp(H*0.60, 340, 520);
  // stars
  initStars();
  return {oldW, oldH};
}
