BuildLevel:
```
function makeSpec(level, cols) {
  const rows = Math.min(8, 5 + Math.floor((level - 1) / 2));
  const cycle = (level - 1) % 5;
  const cells = [];
  for (let r=0;r<rows;r++){
    for (let c=0;c<cols;c++){
      let keep=true, hp=1;
      if (cycle===1){
        const half = Math.round((cols/2 - 0.5) * (0.38 + 0.62*r/Math.max(1,rows-1)));
        keep = Math.abs(c-(cols-1)/2) <= half + .3;
      } else if (cycle===2){
        keep = ((r+c) % 2 === 0);
      } else if (cycle===3){
        keep = !(r>0 && r<rows-1 && (c === Math.floor(cols/3) || c === Math.floor(cols*2/3)));
      } else if (cycle===4){
        const dr = Math.abs(r - (rows-1)/2) / Math.max(1,rows/2);
        const dc = Math.abs(c - (cols-1)/2) / Math.max(1,cols/2);
        keep = dr*0.95 + dc < 1.05;
      }
      if (!keep) continue;
      const seed = (r*37 + c*17 + level*29) % 100;
      if (level >= 3 && seed < Math.min(20, 4 + level*1.6)) hp = 2;
      if (level >= 7 && seed > 94) hp = 3;
      cells.push({r,c,hp});
    }
  }
  // guarantee some bricks
  if (cells.length < 10) { ... fill center rows }
  return {cols, rows, cells};
}
```
