function rebuildBricksForResize() {
 if (!state.grid) return;
 const oldGrid = state.grid;
 const oldBricks = state.bricks;
 const spec = makeSpec(state.level, metrics.cols);
 const map = new Map(oldBricks.map(b=>[`${b.row}:${b.col}`, b]));
 const bricks = [];
 for (const cell of spec.cells) {
   // find old brick near proportional position
   let old = map.get(`${cell.r}:${cell.c}`);
   if (!old) {
      const oc = clamp(Math.round(cell.c * (oldGrid.cols-1) / Math.max(1,spec.cols-1)), 0, oldGrid.cols-1);
      const or = clamp(Math.round(cell.r * (oldGrid.rows-1) / Math.max(1,spec.rows-1)), 0, oldGrid.rows-1);
      old = map.get(`${or}:${oc}`);
   }
   if (old && !old.alive) continue; // destroyed remains destroyed
   const b = makeBrick(cell, spec, old?.hp, 0);
   b.spawn = state.time; // no animation
   b.flash = 0;
   if (old) { b.flash = old.flash; }
   bricks.push(b);
 }
 state.grid = spec; state.bricks = bricks;
}
