  else if (b.x + b.r > W) { b.x = W - b.r; b.vx = -Math.abs(b.vx); wallFx... }
  if (b.y - b.r < 0) { b.y = b.r; b.vy = Math.abs(b.vy); wallFx top; }
  if (b.y - b.r > H) { b.dead = true; return; }
  // paddle
  if (b.vy > 0 && b.y + b.r >= p.y && b.y + b.r <= p.y + p.h + 10 && b.x >= p.x - b.r && b.x <= p.x + p.w + b.r) {
