Collision brick:
```
function collideBrick(b, br) {
  const cx = clamp(b.x, br.x, br.x+br.w);
  const cy = clamp(b.y, br.y, br.y+br.h);
  let nx = b.x - cx, ny = b.y - cy;
  const d2 = nx*nx+ny*ny;
  if (d2 > b.r*b.r) return;
  let penetration;
  if (d2 > 0.0001) {
    const d = Math.sqrt(d2);
    nx /= d; ny /= d;
    penetration = b.r - d;
  } else {
    // center inside brick: push out shortest axis
    const left = b.x - br.x, right = br.x+br.w-b.x, top = b.y-br.y, bottom = br.y+br.h-b.y;
    const m = Math.min(left,right,top,bottom);
    if (m === left) { nx=-1; ny=0; penetration = left + b.r; }
    else if (m === right) { nx=1; ny=0; penetration = right + b.r; }
    else if (m === top) { nx=0; ny=-1; penetration = top + b.r; }
    else { nx=0; ny=1; penetration = bottom + b.r; }
  }
  const dot = b.vx*nx + b.vy*ny;
  if (dot < 0) { b.vx -= 2*dot*nx; b.vy -= 2*dot*ny; }
  b.x += nx * (penetration + 0.2);
  b.y += ny * (penetration + 0.2);
  hitBrick(br, nx, ny);
}
```
